if (
    isinstance(preview, dict)
    and preview.get("status") == "deferred"
):
    if preview.get("native_rejection_stage") == "move_mode_unavailable":
        # This native gate depends on the destination. Its
        # rejection does not rule out the next exact objective.
        route_rejections.append(
            {
                "target_province_id": province_id,
                "status": "move_mode_unavailable",
                "native_rejection_stage": "move_mode_unavailable",
            }
        )
        continue
    if (
        stationary_threats
        or refuge_lifecycle_active
    ):
        route_rejections.append(
            {
                "target_province_id": province_id,
                "status": (
                    "deferred_while_stationary_province_threatened"
                ),
            }
        )
        if candidate_source in {
            "player_held_county_capital",
            "same_realm_vassal_capital",
        }:
            # A rejected move preview cannot veto the
            # independent stationary Native contact reader.
            # Reject this destination, then inspect the next
            # refuge or the current-province one-day horizon.
            continue
        return {
            "policy": "one-life-turn-v1",
            "phase": (
                "native_war_move_readiness_observation_required"
            ),
            "selected_step": None,
            "required_step": (
                "query-native-army-move-readiness"
            ),
            "reason": (
                "the same-frame native preview rejected this "
                "canonical threatened CUnit before route "
                "construction; target enumeration cannot "
                "change the subject's move readiness"
            ),
            "route_preview": preview,
            "route_rejections": route_rejections,
            "active_wars": war_summary,
        }
    if (
        active_route_unsafe
        or isinstance(exact_siege_rejection, dict)
    ):
        route_rejections.append(
            {
                "target_province_id": province_id,
                "status": (
                    "deferred_while_active_route_unsafe"
                    if active_route_unsafe
                    else "deferred_while_exact_siege_rejected"
                ),
            }
        )
        continue
    deferred_advance_step = (
        "life-advance-one-day"
        if "life-advance-one-day" in available_steps
        else "life-advance"
        if "life-advance" in available_steps
        else None
    )
    if deferred_advance_step is not None:
        return {
            "policy": "one-life-turn-v1",
            "phase": "native_war_route_preview_deferred",
            "selected_step": deferred_advance_step,
            "reason": "the same-frame army state rejected a read-only route preview; advance only the existing bounded date step before replanning",
            "route_preview": preview,
            "route_rejections": route_rejections,
            "active_wars": war_summary,
        }
    return {
        "policy": "one-life-turn-v1",
        "phase": "native_war_route_preview_deferred_unsupported",
        "selected_step": None,
        "required_step": "life-advance",
        "reason": "the deferred route preview requires time to advance",
        "route_preview": preview,
        "route_rejections": route_rejections,
        "active_wars": war_summary,
    }
